resolve-auth-method.referenceCode:
function resolveAuthMethod(metadata) {
  if (!Object.hasOwn(metadata, "token_endpoint_auth_method")) {
    return "client_secret_basic";
  }
  const value = metadata.token_endpoint_auth_method;
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError("Invalid authentication method");
  }
  return value;
}
